namespace sv_e00b57c7404943f689764cfb501bd7f5.Services;

public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastCount;
    private string? _lastWarehouseId;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount => _lastCount;

    /// <summary>
    /// Fired whenever the alert count is refreshed. Subscribers must
    /// marshal to the UI thread with InvokeAsync before calling StateHasChanged.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling every 10 seconds for the given warehouse. Ref-counted so
    /// multiple components can subscribe, but only one timer runs.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount > 1 && _lastWarehouseId == warehouseId) return;

        StopTimerInternal();

        _lastWarehouseId = warehouseId;
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>Decrements the subscriber count. Stops the timer when it reaches zero.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopTimerInternal();
        }
    }

    /// <summary>Triggers an immediate refresh (e.g. after switching warehouses).</summary>
    public async Task RefreshNowAsync(string warehouseId)
    {
        _lastWarehouseId = warehouseId;
        _lastCount = await GetLowStockCountAsync(warehouseId);
        await NotifySubscribers();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on first tick
        if (_lastWarehouseId is not null)
        {
            _lastCount = await GetLowStockCountAsync(_lastWarehouseId);
            await NotifySubscribers();
        }

        while (!ct.IsCancellationRequested && _timer is not null)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct)) break;
            }
            catch (OperationCanceledException) { break; }

            if (_lastWarehouseId is not null)
            {
                _lastCount = await GetLowStockCountAsync(_lastWarehouseId);
                await NotifySubscribers();
            }
        }
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private void StopTimerInternal()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        StopTimerInternal();
        GC.SuppressFinalize(this);
    }
}

