@using sv_e00b57c7404943f689764cfb501bd7f5.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="warehouse-label" for="warehouse-dropdown">Warehouse:</label>
    <select id="warehouse-dropdown"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.CurrentWarehouseId = id;
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

.warehouse-selector {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.warehouse-label {
    white-space: nowrap;
    font-weight: 600;
    font-size: 0.85rem;
    color: #555;
}

.warehouse-selector .form-select {
    min-width: 240px;
}

@using sv_e00b57c7404943f689764cfb501bd7f5.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge-wrapper">
    @ChildContent
    @if (AlertService.CurrentAlertCount > 0)
    {
        <span class="badge bg-danger alert-badge">@AlertService.CurrentAlertCount</span>
    }
</span>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    private async Task OnAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

.alert-badge-wrapper {
    position: relative;
    display: inline-flex;
    align-items: center;
}

.alert-badge {
    position: absolute;
    top: -0.4rem;
    right: -0.6rem;
    font-size: 0.65rem;
    padding: 0.2em 0.45em;
    border-radius: 999px;
    line-height: 1;
}

