@page "/dashboard"
@rendermode InteractiveServer
@using sv_e00b57c7404943f689764cfb501bd7f5.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong>
    <span class="text-secondary">(@WarehouseState.CurrentWarehouseId)</span>
</p>

<div class="row g-4 mt-2">
    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low-Stock Alerts</h5>
                <p class="display-4 fw-bold text-danger">@AlertService.CurrentAlertCount</p>
                <p class="text-muted mb-0">items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6 fw-bold">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted mb-0">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">
                    <span class="badge bg-success">Active</span>
                </p>
                <p class="text-muted mb-0">refreshing every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;

        AlertService.StartPolling(WarehouseState.CurrentWarehouseId);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse and fire an immediate refresh
        AlertService.StopPolling();
        AlertService.StartPolling(WarehouseState.CurrentWarehouseId);
        InvokeAsync(async () =>
        {
            await AlertService.RefreshNowAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
        });
    }

    private async Task OnAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
        AlertService.StopPolling();
    }
}

